head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[treeview > M > notifyDataChanged]<br/>트리 아이템이 ItemSet 으로 정의되었을때 바인딩 된 DataCollection 을 TreeView 컴포넌트에 새롭게 반영합니다.",
    "validation" : [
        "refreshCheckboxModel, refreshCheckboxDisableModel 속성 등에 의해 DataCollection 에 반영된 값은 유지됩니다.",
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);	

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        refreshCheckboxModel : true,        
        showCheckbox : true,
    }

    let cList = $c.gcm.createCList(properties);    
    let eList = $c.gcm.createEList(["oncheckboxclick"]);

    let grp_comp = document.querySelector('.tc_group_basic');
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:treeview ' + strNameSpace + ' ' + cList + ' ' + eList + ' id="" dataType="listed" tooltipGroupClass="false" style="width:200px;">';
    strTarget += '<w2:itemset nodeset="data:dlt_Item">';
    strTarget += '<w2:label ref="label"></w2:label>';
    strTarget += '<w2:value ref="value"></w2:value>';
    strTarget += '<w2:depth ref="depth"></w2:depth>';
    strTarget += '<w2:folder ref=""></w2:folder>';
    strTarget += '<w2:checkbox ref="checkbox"></w2:checkbox>';
    strTarget += '<w2:checkboxDisabled ref="disabled"></w2:checkboxDisabled>';
    strTarget += '<w2:image ref=""></w2:image>';
    strTarget += '<w2:iconImage ref=""></w2:iconImage>';
    strTarget += '<w2:selectedImage ref=""></w2:selectedImage>';
    strTarget += '<w2:expandedImage ref=""></w2:expandedImage>';
    strTarget += '<w2:leafImage ref=""></w2:leafImage>';
    strTarget += '</w2:itemset>';
    strTarget += '</w2:treeview>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "treeview",
        strTarget,
        grp_comp
    );
}



scwin.btn_getCheckbox_onclick = function (e) {
    let rtn = '';

    rtn = dlt_Item.getColData("checkbox");
    wf_body_bottom.getObj("scwin").setReturnValue("checkbox 컬럼 값 : "+ rtn);         
};



scwin.btn_notifyDataChanged_onclick = function (e) {
	target1.notifyDataChanged();  

    scwin.target1_oncheckboxclick();
};



scwin.target1_oncheckboxclick = function (value, node, index) {
    scwin.btn_getCheckbox_onclick();
}
